from html.parser import HTMLParser
class P(HTMLParser):
 def __init__(self): super().__init__(); self.inside=0; self.parts=[]
 def handle_starttag(self,tag,attrs):
  if tag=='main': self.inside+=1
  elif tag=='article' and self.inside: self.inside+=1
 def handle_endtag(self,tag):
  if tag in ('main','article') and self.inside: self.inside-=1
 def handle_data(self,data):
  if self.inside: self.parts.append(data)
p=P();p.feed(open('/tmp/next15-middleware.html').read()); s=' '.join(p.parts)
for term in ('Middleware function','Set response headers','Matching Paths'):
 i=s.find(term); print(term, s[i:i+1100] if i>=0 else 'missing')
